<script lang="ts">
import {onMount,tick} from 'svelte';import Icon from './Icon.svelte';import Field from './Field.svelte';import DatePicker from './DatePicker.svelte';import {dateISO} from './calendar';import {appointmentInput,maskTime,timeValue,splitOffice} from './appointment';import {saveAppointment,type Achievement,type AppointmentContext} from './bridge';
let {profile,context,saved,t,language,onclose,onsaved}:{profile:string;context:AppointmentContext;saved:Achievement|null;t:(key:string)=>string;language:string;onclose:()=>void;onsaved:(item:Achievement)=>void}=$props();
const initial=()=>appointmentInput(context,saved?.appointment);let draft=$state(initial());let busy=$state(false);let error=$state('');let attempted=$state(false);let dialog:HTMLDialogElement;let officeRoot:HTMLDivElement;let officePopup=$state<HTMLDivElement>();let open=$state(false);let active=$state(0);let position=$state({left:0,top:0,width:0,height:220});
const valid=$derived(Boolean(dateISO(draft.date)&&timeValue(draft.time)));const errorKeys:Record<string,string>={appointment_date_invalid:'Требуется существующая дата: ДД.ММ.ГГГГ',appointment_time_invalid:'Допустимое время: 00:00–23:59',appointment_field_invalid:'Проверить данные записи'};
onMount(()=>{dialog.showModal();return()=>dialog.close();});
async function save(){attempted=true;if(!valid||busy)return;busy=true;error='';try{const value=await saveAppointment(profile,saved?.id??null,{...draft,date:dateISO(draft.date)!});onsaved(value);}catch(e){error=errorKeys[String(e)]??'Не удалось сохранить достижение';}finally{busy=false;}}
async function showOffices(){if(!context.offices.length)return;const r=officeRoot.getBoundingClientRect();const below=window.innerHeight-r.bottom-12;const above=r.top-12;const height=Math.min(220,Math.max(below,above));position={left:r.left,top:below>=140||below>=above?r.bottom+5:Math.max(8,r.top-height-5),width:r.width,height};open=true;active=0;await tick();officePopup?.showPopover?.();officePopup?.focus();}
function choose(index:number){const label=context.offices[index];if(label){Object.assign(draft,splitOffice(label));}open=false;officeRoot.querySelector('input')?.focus();}
function officeKey(e:KeyboardEvent){if(e.key==='Escape'){e.preventDefault();e.stopPropagation();open=false;officeRoot.querySelector('input')?.focus();}else if(e.key==='ArrowDown'||e.key==='ArrowUp'){e.preventDefault();active=Math.max(0,Math.min(context.offices.length-1,active+(e.key==='ArrowDown'?1:-1)));officePopup?.querySelector(`[data-index="${active}"]`)?.scrollIntoView({block:'nearest'});}else if(e.key==='Enter'){e.preventDefault();choose(active);}else if(e.key==='Tab')open=false;}
function editTime(e:Event){const input=e.currentTarget as HTMLInputElement;const count=input.value.slice(0,input.selectionStart??input.value.length).replace(/\D/g,'').length;draft.time=maskTime(input.value);input.value=draft.time;let cursor=count+(count>=2?1:0);input.setSelectionRange(cursor,cursor);}
function timeKey(e:KeyboardEvent){const input=e.currentTarget as HTMLInputElement;if(e.key==='Backspace'&&input.selectionStart===input.selectionEnd&&input.selectionStart===3){e.preventDefault();draft.time=maskTime(input.value.slice(0,1)+input.value.slice(3));input.value=draft.time;input.setSelectionRange(1,1);}}
</script>
<svelte:window onpointerdown={e=>{if(open&&!officeRoot?.contains(e.target as Node))open=false;}}/>
<dialog class="appointment-dialog" bind:this={dialog} oncancel={e=>{e.preventDefault();if(!busy)onclose();}}>
<form onsubmit={e=>{e.preventDefault();void save();}}>
<h2><Icon name="calendar"/>{t(saved?'Исправить данные записи':'Подтвердить запись')}</h2><p class="muted intro">{t('Сохранить запись для напоминания в календаре.')}</p>
<fieldset disabled={busy}><div class="appointment-datetime"><DatePicker label={t('Дата')} bind:value={draft.date} {language} {t}/><label class="profile-field time-field"><span>{t('Время')}</span><input aria-label={t('Время')} value={draft.time} oninput={editTime} onkeydown={timeKey} inputmode="numeric" maxlength="5" autocomplete="off" placeholder="00:00"/></label></div>
{#if attempted&&!valid}<p class="field-error" role="alert">{t(!dateISO(draft.date)?'Требуется существующая дата: ДД.ММ.ГГГГ':'Допустимое время: 00:00–23:59')}</p>{/if}
<div class="office-edit" bind:this={officeRoot}><div class="profile-field"><Icon name="office"/><label><small>{t('Офис')}</small><input aria-label={t('Офис')} bind:value={draft.office} placeholder={t('Выбрать офис или ввести название')} maxlength="2048" onkeydown={e=>{if(e.key==='ArrowDown'){e.preventDefault();void showOffices();}}}/></label>{#if context.offices.length}<button type="button" class="icon-button" aria-label={t('Выбрать офис')} aria-expanded={open} onclick={()=>{if(open)open=false;else void showOffices();}}><Icon name="chevron-down" size={18}/></button>{/if}
</div>{#if open}<div class="popup appointment-offices" popover="manual" bind:this={officePopup} role="listbox" tabindex="-1" aria-label={t('Офис')} style:left={`${position.left}px`} style:top={`${position.top}px`} style:width={`${position.width}px`} style:max-height={`${position.height}px`} onkeydown={officeKey}>{#each context.offices as office,index}{@const parts=splitOffice(office)}<button type="button" role="option" aria-selected={draft.office===parts.office} class:highlight={active===index} data-index={index} onpointermove={()=>active=index} onclick={()=>choose(index)}><strong>{parts.office}</strong>{#if parts.address}<small>{parts.address}</small>{/if}</button>{/each}</div>{/if}</div>
<Field label={t('Адрес')} icon="pin" bind:value={draft.address} maxlength={4096}/><div class="confirmation-field"><Field label={t('Номер подтверждения')} icon="id" bind:value={draft.confirmation} maxlength={512}/></div>
</fieldset><p class="muted privacy"><Icon name="lock" size={15}/>{t('Данные хранятся локально.')}</p>
{#if error}<p class="error" role="alert">{t(error)}</p>{/if}
<div class="appointment-actions"><button type="button" disabled={busy} onclick={onclose}>{t('Отмена')}</button><button class="primary" type="submit" disabled={busy}><Icon name="check"/>{t(busy?'Сохранение…':'Сохранить')}</button></div>
</form></dialog>
<style>
.appointment-dialog{width:min(610px,calc(100vw - 32px));max-height:calc(100vh - 32px);overflow:auto;padding:22px;border:1px solid var(--strong);border-radius:12px;background:var(--bg);color:var(--text)}.appointment-dialog::backdrop{background:#0008}h2{display:flex;align-items:center;gap:10px;font-size:19px;margin:0 0 12px}.intro{margin:0 0 16px;font-size:12px}fieldset{border:0;margin:0;padding:0;display:flex;flex-direction:column;gap:12px;min-width:0}.appointment-datetime{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:12px}.time-field{display:flex;gap:8px;height:58px}.time-field>span{color:var(--muted);flex:1}.time-field input{width:62px;flex:none;font-variant-numeric:tabular-nums;text-align:right}.office-edit{min-width:0}.office-edit label{display:flex;flex:1;min-width:0;flex-direction:column}.office-edit input{font:inherit;background:none;color:var(--text);border:0;outline:none;min-width:0;width:100%;height:22px;padding:0}.office-edit .icon-button{width:28px;height:28px;min-height:28px;padding:4px}.confirmation-field{max-width:280px}.privacy{display:flex;gap:6px;align-items:center;font-size:12px;margin:14px 0}.appointment-actions{display:flex;justify-content:flex-end;gap:10px;margin-top:16px}.primary{background:var(--accent);border-color:var(--accent);color:#fff}.field-error{color:#E4685D;font-size:12px;margin:0}.appointment-offices{position:fixed;inset:auto;margin:0;z-index:40;overflow:auto;outline:none;color:var(--text)}.appointment-offices button{display:flex;flex-direction:column;align-items:flex-start;gap:4px;padding:9px 10px;text-align:left}.appointment-offices strong{font-weight:400}.appointment-offices small{font-size:11px;color:var(--muted)}.appointment-offices .highlight{background:var(--selection)}
</style>
